CREATE OR REPLACE VIEW SEC.MAP_USER_REGION
  COMMENT = 'User entitlement mapping for ActiveMeterFilter, RegionFilter. USERNAME must match CURRENT_USER().'
AS
SELECT UPPER(USERNAME) AS USERNAME, REGION
FROM RAW_ENERGY_DW.USER_REGION_ACCESS;
